{"code":"import json
from collections import defaultdict

start_date = "2026-07-03"
end_date = "2026-10-01"
accounts = list_accounts("CUST-0010")
account_ids = [a["account_id"] for a in accounts]
balances = {aid: get_balance(aid) for aid in account_ids}
transactions = {aid: get_transactions(aid, start_date, end_date) for aid in account_ids}

result_accounts = []
total_available = 0.0

for aid in account_ids:
    bal = balances[aid]
    available_balance = round(bal["available_balance"], 2)
    total_available += available_balance

    spend = defaultdict(float)
    large_ids = []
    for t in transactions[aid]:
        amount = t["amount"]
        if amount < 0:
            abs_amt = abs(amount)
            spend[t["category"]] += abs_amt
            if abs_amt > 1000:
                large_ids.append(t["transaction_id"])

    spend_by_category = {cat: round(v, 2) for cat, v in spend.items()}
    large_ids.sort()

    result_accounts.append({
        "account_id": aid,
        "available_balance": available_balance,
        "spend_by_category": spend_by_category,
        "large_debit_ids": large_ids,
    })

total_available = round(total_available, 2)

output = {
    "customer_id": "CUST-0010",
    "accounts": result_accounts,
    "total_available_balance": total_available,
}
print(json.dumps(output, indent=2))"}
